import React from 'react';

// Sacred Gyuto Monastery Circular Emblem Seal (Figma Logo: Gyuto Logo 2)
export function GyutoEmblem({ size = 190, width, height, className = "gt-emblem-seal" }) {
  const w = width || (height ? Math.round(height * 227 / 190) : Math.round(size * 227 / 190));
  const h = height || size;
  return (
    <img
      src="/images/gyuto-logo.png"
      alt="Gyuto Tantric Monastery Seal"
      width={w}
      height={h}
      className={className}
      style={{
        objectFit: "contain",
        display: "block",
      }}
    />
  );
}

// Sacred Tibetan Vajra (Dorje) - Exact match to user screenshot and Figma Layer_x0020_1
export function TibetanVajra({ width = 72, height = 24, className = '' }) {
  return (
    <img
      src="/images/tibetan-vajra.png"
      alt="Sacred Tibetan Dorje Vajra"
      width={width}
      height={height}
      className={`gt-vajra-icon ${className}`}
      style={{
        width: `${width}px`,
        height: `${height}px`,
        objectFit: 'contain',
        display: 'inline-block',
        verticalAlign: 'middle',
        flexShrink: 0
      }}
    />
  );
}

